import { DemoRecManager } from 'demorec/DemoRecManager';

import { BatteryPackType } from 'demorec/BatteryPackType';

import { BatteryPack } from 'demorec/BatteryPack';

import { PackChooseComponent,config } from 'gui/pack/PackChooseComponent';


/* generated by template umlp.gui2ts.TSImports*/

import {
  Directive,
  Component,
  Input,
  Output,
  EventEmitter,
  TemplateRef,
} from '@angular/core';

import { ActivatedRoute, Router } from '@angular/router';
import {Option} from "@umlp/input";

const newOption: Option = new Option("NEW");

@Component({
  standalone:true,
  imports:[...config.imports],
  selector: config.selector,
  templateUrl: config.templateUrl,
  styles: config.styles,
  styleUrls: config.styleUrls
})
export class PackChoose extends PackChooseComponent {

  public chosenPack = new EventEmitter<BatteryPack>()

  public bPackEntry: string = "";
  public bPackOptions: Option[] = [newOption];

  public ngOnInit(): void {
    DemoRecManager.getBatteryPackList().then(gemPromiseRes => {
      const bPacks = gemPromiseRes;
      bPacks.loadAll().then(() => {
        for (const bPack of bPacks) {
          let value = bPack.getGemId() + "";
          this.bPackOptions.push(new Option(value, bPack.getName()));
        }
        this.bPackOptions = this.bPackOptions.slice();
      });
    });
  }

  public override getSelectPackOptions(): Array<Option> {
    return this.bPackOptions;
  }

  public override getSelectPackEntry(): string {
    return this.bPackEntry;
  }

  public override setSelectPackEntry(value: string): void {
    this.bPackEntry = value;
    DemoRecManager.getBatteryPackSure(Number(value)).then( p =>
        this.chosenPack.emit(p)
    )
  }

  public override getCreatePackCondition(): boolean {
    return this.getSelectPackEntry() === newOption.getValue();
  }

  public override addNewBatteryPack() {
    return (pack) => {
      //this.pack.build()
      this.bPackOptions.push(new Option(pack.getGemId(), pack.getName()))
      this.setSelectPackEntry(pack.getGemId())
    }
  }

}


